INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C1','kor',2,2,'u6',1,'매체와 매체 자료 — 서로 소통하게 이어 주는 도구인 매체(책·텔레비전·스마트폰·컴퓨터·태블릿·인터넷)와 매체로 소통되는 정보인 매체 자료(그림책·만화·뉴스·광고·웹툰·애니메이션·영화)를 구분하기',ARRAY['2국06-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C2','kor',2,2,'u6',1,'책과 영상의 다른 점 — 책은 글과 그림을 보며 상상하고, 영상은 움직임과 소리를 생생하게 느끼게 함을 알고 매체마다 좋은 점이 다름을 인정하며 매체 경험을 나누기',ARRAY['2국06-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C3','kor',2,2,'u6',3,'공익 광고의 글과 그림이 나타내는 뜻 — 여러 사람의 이익을 위한 공익 광고에서 글로 알 수 있는 내용과 그림으로 알 수 있는 내용을 함께 살펴 전하려는 뜻을 찾기',ARRAY['2국06-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C4','kor',2,2,'u6',3,'글과 그림을 관련지으며 만화 읽기 — 장면마다 인물의 말(말풍선)과 표정·몸짓, 글자 모양과 크기를 관련지어 무슨 일이 있었는지와 인물의 마음을 알고 더 재미있게 읽기',ARRAY['2국06-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C5','kor',2,2,'u6',5,'그림책 내용 파악하기 — 「오염물이 터졌다」에서 누구에게 어떤 일이 일어났는지, 인물이 한 일과 마음, 마음먹은 일을 글과 그림에서 찾기',ARRAY['2국06-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C6','kor',2,2,'u6',5,'그림책의 글과 그림 관련짓기 — 그림의 색(검은색 = 오염물)·글자 크기·인물 표정이 글과 어떻게 이어지는지 말하고, 장면 속에서 낱말(뒤숭숭하다·채·행동)의 뜻을 짐작하기',ARRAY['2국06-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C7','kor',2,2,'u6',7,'누리집 살펴보기 — 홈페이지의 순우리말 누리집에서 차림표(관람·전시·교육·자료·소개, 학교 소개의 오시는 길·교실 배치도·학교 상징·교가)를 보고 알 수 있는 내용을 찾고, 본 것과 느낌을 이어서 발표하기',ARRAY['2국06-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C8','kor',2,2,'u6',7,'매체 자료를 바르게 쓰는 태도 — 인터넷에 남긴 사진·글·기록(디지털 발자국)은 쉽게 지워지지 않으므로 다른 사람의 사진이나 정보를 허락 없이 퍼뜨리지 않기',ARRAY['2국06-01']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C9','kor',2,2,'u6',9,'게시물 계획하기 — 학급 누리집에 올릴 우리 반 소개 게시물의 주제를 정하고, 주제에 알맞은 내용과 어울리는 그림·사진을 떠올리고, 사진은 나온 친구에게 허락받기',ARRAY['2국06-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C10','kor',2,2,'u6',9,'게시물 점검하고 칭찬하기 — 다른 사람이 궁금해할 내용인지, 전하려는 내용이 글에 드러났는지, 그림·사진이 글과 어울리는지 점검하고, 친구의 글과 그림을 구체적으로 칭찬하기',ARRAY['2국03-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C11','kor',2,2,'u6',11,'매체 활용 태도 점검하기 — 주로 쓰는 매체와 하는 일을 떠올려 매체 이용 시간표를 쓰고, 정한 시간만큼 쓰고 스스로 끄는 등 더 나은 매체 활용을 다짐하기(아예 끊는 것이 목표가 아님)',ARRAY['2국06-01']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C12','kor',2,2,'u6',11,'매체로 소통할 때 고운 말 쓰기 — 보이지 않는 상대도 마음을 다칠 수 있으므로 이웃에게 건네는 말·댓글·게시물에 고운 말을 쓰고, 좋아하는 매체를 까닭과 함께 소개하기',ARRAY['2국06-02']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u6-C13','kor',2,2,'u6',11,'글자와 다르게 소리 나는 낱말 — 그렇게[그러케]·받아서[바다서]·않고[안코]처럼 글자와 다르게 소리 나는 낱말을 바르게 읽고, 쓸 때는 「깨끗이 씻었습니다」처럼 글자대로 쓰기(기초 다지기)',ARRAY['2국04-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X01','kor',2,'u6',ARRAY['K2-2-u6-C1']::text[],'매체와 매체 자료를 헷갈리거나, 소통과 상관없는 물건(운동화·필통)을 매체로 여긴다','「이것으로 생각을 주고받을 수 있나?」 — 되면 매체, 그 안에서 보는 내용은 매체 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X02','kor',2,'u6',ARRAY['K2-2-u6-C2','K2-2-u6-C12']::text[],'한 매체가 언제나 더 좋다고 여기거나, 좋아하는 매체를 나만 알고 나누지 않는다','「책은 ~이 좋고, 영상은 ~이 좋아」 — 두 쪽 모두 좋은 점 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X03','kor',2,'u6',ARRAY['K2-2-u6-C2']::text[],'책과 영상의 특징을 바꿔 안다(책에서 소리를 듣는다, 영상에서 종이를 넘긴다)','눈으로 읽고 상상하면 책, 귀로 듣고 움직임을 보면 영상') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X04','kor',2,'u6',ARRAY['K2-2-u6-C3','K2-2-u6-C4','K2-2-u6-C6']::text[],'글만 보거나 그림만 보고 뜻을 짐작한다','글 한 줄 + 그림 한 곳을 손가락으로 함께 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X05','kor',2,'u6',ARRAY['K2-2-u6-C3']::text[],'광고의 겉모습(풀처럼 보이는 비닐봉지)을 그대로 사실로 받아들여 전하려는 뜻을 놓친다','「이 광고는 우리에게 무엇을 하자고 할까?」 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X06','kor',2,'u6',ARRAY['K2-2-u6-C4']::text[],'만화에서 말풍선·인물 표정·글자 크기를 보지 않고 넘긴다','장면마다 얼굴 표정 한 낱말로 말해 보기(신남·아픔·걱정)') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X07','kor',2,'u6',ARRAY['K2-2-u6-C5']::text[],'글에 없는 내용으로 답하거나 인물이 한 일을 바꿔 안다','「누가 했지?」 하고 그 장면의 글과 그림을 다시 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X08','kor',2,'u6',ARRAY['K2-2-u6-C6']::text[],'낱말의 뜻을 장면과 상관없이 고른다','낱말이 나온 장면을 다시 읽고 뜻을 넣어 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X09','kor',2,'u6',ARRAY['K2-2-u6-C7']::text[],'누리집에서 알 수 없는 정보도 있다고 여기거나, 차림표를 보지 않고 내용을 찾는다','차림표 이름을 먼저 읽고 「여기에 무엇이 있을까?」 짐작하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X10','kor',2,'u6',ARRAY['K2-2-u6-C8','K2-2-u6-C9']::text[],'다른 사람의 사진·정보를 허락 없이 올리거나 퍼뜨린다(인터넷 기록은 쉽게 지울 수 있다고 여긴다)','올리기 전에 「올려도 돼?」 — 한 번 올리면 디지털 발자국이 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X11','kor',2,'u6',ARRAY['K2-2-u6-C9','K2-2-u6-C10']::text[],'주제와 상관없는 내용을 쓰거나 글과 어울리지 않는 그림·사진을 고른다','글 한 줄과 그림을 나란히 놓고 같은 이야기인지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X12','kor',2,'u6',ARRAY['K2-2-u6-C10','K2-2-u6-C12']::text[],'누리집·매체는 읽는 사람이 안 보인다며 고운 말을 쓰지 않는다','「이 말을 얼굴 보고도 할 수 있나?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X13','kor',2,'u6',ARRAY['K2-2-u6-C10','K2-2-u6-C12']::text[],'칭찬이나 소개를 까닭 없이 막연하게 하거나 비교·놀림으로 한다','「무엇이 + 왜 좋은지」 한 문장으로 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X14','kor',2,'u6',ARRAY['K2-2-u6-C11']::text[],'매체 쓰는 시간을 스스로 조절하지 않거나, 아예 끊는 것만 바른 태도로 여긴다','시간표에 「언제 · 얼마나 · 끄는 때」 적기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u6-X15','kor',2,'u6',ARRAY['K2-2-u6-C13']::text[],'소리 나는 대로 쓰거나 글자대로 읽어 소리와 글자를 헷갈린다','읽을 때는 [소리]대로, 쓸 때는 글자대로 — 둘을 나란히 적어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
