INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L01_basic#2','kor',2,2,'u6','L01','g2_2_kor_u6_L01_basic','lesson_basic','K2-2-u6-C1',1,'mc','auto','다음 가운데 매체 자료는 어느 것인가요?',ARRAY['K2-2-u6-X01']::text[],false,'{"seq":2,"concept":"K2-2-u6-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 매체 자료는 어느 것인가요?","options":[{"t":"그림책","correct":true},{"t":"필통","mis":"K2-2-u6-X01"},{"t":"운동장","mis":"K2-2-u6-X01"}],"explanation":["그림책이에요.","지도서 257쪽이에요.","매체로 만나는 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
