INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L01_challenge#7','kor',2,2,'u6','L01','g2_2_kor_u6_L01_challenge','lesson_challenge','K2-2-u6-C2',3,'mc','auto','「종이를 넘기면서 한 글자, 한 글자 읽다 보니까 이야기 속으로 빠져들었어.」는 어떤 매체로 본 경험인가요?',ARRAY['K2-2-u6-X03']::text[],false,'{"seq":7,"concept":"K2-2-u6-C2","difficulty":3,"kind":"mc","stem":"「종이를 넘기면서 한 글자, 한 글자 읽다 보니까 이야기 속으로 빠져들었어.」는 어떤 매체로 본 경험인가요?","options":[{"t":"책","correct":true},{"t":"영상","mis":"K2-2-u6-X03"},{"t":"라디오","mis":"K2-2-u6-X03"}],"explanation":["책이에요.","168쪽이에요.","종이를 넘겨요."],"asset":{"type":"speech","turns":[{"who":"소현","text":"「토끼의 재판」을 책으로 읽으니 재판하는 모습을 상상할 수 있어서 좋아."},{"who":"다훈","text":"종이를 넘기면서 한 글자, 한 글자 읽다 보니까 이야기 속으로 빠져들었어."},{"who":"다훈","text":"「토끼의 재판」을 영상으로 보니 소리를 들으며 인물들의 움직임을 볼 수 있어서 그 모습이 더 생생하게 느껴져."},{"who":"소현","text":"영상 속 호랑이 소리가 진짜 호랑이가 우는 소리처럼 실감 나게 느껴졌어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L01_challenge#8','kor',2,2,'u6','L01','g2_2_kor_u6_L01_challenge','lesson_challenge','K2-2-u6-C1',4,'sa','auto','책, 텔레비전, 스마트폰, 컴퓨터처럼 서로 소통하게 이어 주는 도구를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u6-C1","difficulty":4,"kind":"sa","stem":"책, 텔레비전, 스마트폰, 컴퓨터처럼 서로 소통하게 이어 주는 도구를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["매체"],"explanation":["매체예요.","지도서 257쪽이에요.","소통을 이어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L01_challenge#9','kor',2,2,'u6','L01','g2_2_kor_u6_L01_challenge','lesson_challenge','K2-2-u6-C2',4,'essay','teacher','「토끼의 재판」을 책으로 읽을 때와 영상으로 볼 때의 좋은 점을 하나씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u6-C2","difficulty":4,"kind":"essay","stem":"「토끼의 재판」을 책으로 읽을 때와 영상으로 볼 때의 좋은 점을 하나씩 쓰세요.","answer_guide":{"answer":"예: 책으로 읽으면 글과 그림을 보며 재판 모습을 상상할 수 있다. 영상으로 보면 호랑이 소리와 움직임을 생생하게 느낄 수 있다.","scoring_points":["책의 좋은 점을 썼어요","영상의 좋은 점을 썼어요"]},"explanation":["둘 다 써요.","169쪽 2번이에요.","저마다 좋은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
