INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L03_basic#2','kor',2,2,'u6','L03','g2_2_kor_u6_L03_basic','lesson_basic','K2-2-u6-C3',1,'mc','auto','『국어』 170쪽 공익 광고의 큰 글은?',ARRAY['K2-2-u6-X04']::text[],false,'{"seq":2,"concept":"K2-2-u6-C3","difficulty":1,"kind":"mc","stem":"『국어』 170쪽 공익 광고의 큰 글은?","options":[{"t":"「엄마, 저 풀은 이름이 뭐예요?」","correct":true},{"t":"「반려동물은 가족입니다」","mis":"K2-2-u6-X04"},{"t":"「불이야!」","mis":"K2-2-u6-X04"}],"explanation":["풀 이름을 묻는 글이에요.","170쪽이에요.","글을 살펴요."],"asset":{"type":"passage","lines":["그림: 흙 위에 초록색 비닐봉지가 풀처럼 솟아 있어요.","큰 글: 「엄마, 저 풀은 이름이 뭐예요?」","작은 글: 땅속에 묻어도 썩지 않는 쓰레기들이 토양을 오염시키고 있습니다."],"title":"『국어』 170쪽 공익 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
