INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L03_challenge#7','kor',2,2,'u6','L03','g2_2_kor_u6_L03_challenge','lesson_challenge','K2-2-u6-C3',3,'mc','auto','지도서 251쪽 공익 광고에서 전하고자 하는 뜻은?',ARRAY['K2-2-u6-X05','K2-2-u6-X04']::text[],false,'{"seq":7,"concept":"K2-2-u6-C3","difficulty":3,"kind":"mc","stem":"지도서 251쪽 공익 광고에서 전하고자 하는 뜻은?","options":[{"t":"반려동물은 장난감이 아니라 가족이에요","correct":true},{"t":"강아지 인형을 사세요","mis":"K2-2-u6-X05"},{"t":"털실로 인형을 떠요","mis":"K2-2-u6-X04"}],"explanation":["가족이에요.","지도서 251쪽이에요.","글과 그림을 함께요."],"asset":{"type":"passage","lines":["큰 글: 가족이 되고 싶었지만 장난감이 되었습니다!","그림: 털실로 뜬 강아지 인형","작은 글: 반려동물은 싫증 나면 쉽게 외면하고 버리는 장난감이 아닙니다.","우리와 감정을 나누는 친구이고 가족입니다."],"title":"지도서 251쪽 공익 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
