INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L03_challenge#9','kor',2,2,'u6','L03','g2_2_kor_u6_L03_challenge','lesson_challenge','K2-2-u6-C4',4,'essay','teacher','『국어』 173쪽 6번 — 만화를 읽을 때 글과 그림을 함께 보면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u6-C4","difficulty":4,"kind":"essay","stem":"『국어』 173쪽 6번 — 만화를 읽을 때 글과 그림을 함께 보면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 만화에서 글과 그림이 있으면 그 내용을 더욱 생생하게 이해할 수 있어서 좋다.","scoring_points":["글과 그림을 함께 말했어요","좋은 점을 썼어요"]},"explanation":["생생하게 알아요.","173쪽 예시 답안이에요.","둘이 함께요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L03_challenge#10','kor',2,2,'u6','L03','g2_2_kor_u6_L03_challenge','lesson_challenge','K2-2-u6-C3',4,'essay','teacher','『국어』 170쪽 공익 광고에서 인상 깊었던 글이나 그림 하나와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u6-C3","difficulty":4,"kind":"essay","stem":"『국어』 170쪽 공익 광고에서 인상 깊었던 글이나 그림 하나와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「엄마, 저 풀은 이름이 뭐예요?」라는 글이 인상 깊었다. 썩지 않는 쓰레기를 풀로 착각한 것 같아서 기억에 남았다.","scoring_points":["글이나 그림을 하나 골랐어요","까닭을 썼어요"]},"explanation":["까닭과 함께요.","171쪽 2번이에요.","내 생각이에요."],"asset":{"type":"passage","lines":["그림: 흙 위에 초록색 비닐봉지가 풀처럼 솟아 있어요.","큰 글: 「엄마, 저 풀은 이름이 뭐예요?」","작은 글: 땅속에 묻어도 썩지 않는 쓰레기들이 토양을 오염시키고 있습니다."],"title":"『국어』 170쪽 공익 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L05_basic#1','kor',2,2,'u6','L05','g2_2_kor_u6_L05_basic','lesson_basic','K2-2-u6-C5',1,'mc','auto','그림책 「오염물이 터졌다」에서 꿈 때문에 마음이 뒤숭숭한 인물은?',ARRAY['K2-2-u6-X07']::text[],false,'{"seq":1,"concept":"K2-2-u6-C5","difficulty":1,"kind":"mc","stem":"그림책 「오염물이 터졌다」에서 꿈 때문에 마음이 뒤숭숭한 인물은?","options":[{"t":"철이","correct":true},{"t":"영이","mis":"K2-2-u6-X07"},{"t":"엄마","mis":"K2-2-u6-X07"}],"explanation":["철이예요.","174쪽이에요.","첫 장면이에요."],"asset":{"type":"passage","lines":["꿈 때문에 마음이 뒤숭숭한 철이는 아침 식사 시간에 음식을 남기지 않고 다 먹었어요.","그런데 집 안 곳곳에서 물이 더러워지고 낭비돼요.","영이는 먹다 남긴 우유를 싱크대에 몰래 부어요.","아빠는 빨래를 세 번이나 나누어 돌려요.","엄마는 샴푸를 많이 쓰고, 물을 튼 채로 욕실 청소를 해요.","집 아래 물길에 까만 오염물이 차오르더니 펑 하고 터져 버려요!","「설마 다 꿈이었나?」 깨어난 철이는 두 볼을 세게 꼬집어 보아요.","철이는 오염물이 터지기 전에 물 오염과 낭비를 막겠다고 마음먹어요."],"title":"『국어』 174~181쪽 「오염물이 터졌다」(송수혜) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
