INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L05_challenge#7','kor',2,2,'u6','L05','g2_2_kor_u6_L05_challenge','lesson_challenge','K2-2-u6-C5',3,'mc','auto','이 그림책이 우리에게 전하려는 뜻으로 알맞은 것은?',ARRAY['K2-2-u6-X07']::text[],false,'{"seq":7,"concept":"K2-2-u6-C5","difficulty":3,"kind":"mc","stem":"이 그림책이 우리에게 전하려는 뜻으로 알맞은 것은?","options":[{"t":"물을 아끼고 더럽히지 말아야 해요","correct":true},{"t":"우유를 많이 마셔요","mis":"K2-2-u6-X07"},{"t":"빨래를 하지 말아요","mis":"K2-2-u6-X07"}],"explanation":["물을 아껴요.","지도서 253쪽 제재 소개예요.","수질 오염이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L05_challenge#8','kor',2,2,'u6','L05','g2_2_kor_u6_L05_challenge','lesson_challenge','K2-2-u6-C6',4,'sa','auto','「몸을 움직여 동작을 하거나 어떤 일을 함」을 뜻하는 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u6-C6","difficulty":4,"kind":"sa","stem":"「몸을 움직여 동작을 하거나 어떤 일을 함」을 뜻하는 낱말을 두 글자로 쓰세요.","answer":["행동"],"explanation":["행동이에요.","182쪽이에요.","철이의 행동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L05_challenge#9','kor',2,2,'u6','L05','g2_2_kor_u6_L05_challenge','lesson_challenge','K2-2-u6-C5',4,'essay','teacher','『국어』 182쪽 — 철이에게 하고 싶은 질문을 하나 쓰고, 철이가 할 만한 대답도 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u6-C5","difficulty":4,"kind":"essay","stem":"『국어』 182쪽 — 철이에게 하고 싶은 질문을 하나 쓰고, 철이가 할 만한 대답도 쓰세요.","answer_guide":{"answer":"예: 질문 — 물 오염과 낭비를 막으려고 무엇을 할 계획이니? 대답 — 이를 닦을 때 컵을 쓰고, 남은 음식은 싱크대에 버리지 않을 거야.","scoring_points":["질문을 썼어요","이야기와 어울리는 대답이에요"]},"explanation":["묻고 답해요.","182쪽 예시 답안이에요.","이야기와 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L05_challenge#10','kor',2,2,'u6','L05','g2_2_kor_u6_L05_challenge','lesson_challenge','K2-2-u6-C6',4,'essay','teacher','물을 낭비했던 경험이나 물을 아끼려고 한 노력을 「오염물이 터졌다」와 이어서 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u6-C6","difficulty":4,"kind":"essay","stem":"물을 낭비했던 경험이나 물을 아끼려고 한 노력을 「오염물이 터졌다」와 이어서 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 나도 영이처럼 남은 우유를 싱크대에 부은 적이 있다. 이제는 먹을 만큼만 따르고 남기지 않겠다.","scoring_points":["내 경험을 썼어요","그림책과 이어서 썼어요"]},"explanation":["내 생활과 이어요.","183쪽이에요.","실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
