INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L07_challenge#9','kor',2,2,'u6','L07','g2_2_kor_u6_L07_challenge','lesson_challenge','K2-2-u6-C7',4,'essay','teacher','찾아본 누리집 하나를 골라, 그 누리집에서 본 글이나 사진과 그때 든 느낌을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u6-C7","difficulty":4,"kind":"essay","stem":"찾아본 누리집 하나를 골라, 그 누리집에서 본 글이나 사진과 그때 든 느낌을 쓰세요.","answer_guide":{"answer":"예: 우리 학교 누리집에서 운동회 사진을 보았다. 친구들과 달리기했던 날이 떠올라 즐거웠다.","scoring_points":["본 글이나 사진을 썼어요","느낌을 썼어요"]},"explanation":["본 것과 느낌이에요.","186쪽이에요.","내 경험이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
