INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L09_challenge#7','kor',2,2,'u6','L09','g2_2_kor_u6_L09_challenge','lesson_challenge','K2-2-u6-C10',3,'mc','auto','친구의 게시물에 보완할 점을 말하는 방법으로 알맞은 것은?',ARRAY['K2-2-u6-X13']::text[],false,'{"seq":7,"concept":"K2-2-u6-C10","difficulty":3,"kind":"mc","stem":"친구의 게시물에 보완할 점을 말하는 방법으로 알맞은 것은?","options":[{"t":"「사진 아래에 무슨 행사인지 한 줄 쓰면 더 잘 알겠어.」","correct":true},{"t":"「이걸 누가 봐?」","mis":"K2-2-u6-X13"},{"t":"「다시는 만들지 마.」","mis":"K2-2-u6-X13"}],"explanation":["부드럽게 알려요.","지도서 265쪽이에요.","도움이 되게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L09_challenge#8','kor',2,2,'u6','L09','g2_2_kor_u6_L09_challenge','lesson_challenge','K2-2-u6-C9',4,'sa','auto','누리집에 올린 글·그림·사진 같은 자료를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u6-C9","difficulty":4,"kind":"sa","stem":"누리집에 올린 글·그림·사진 같은 자료를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["게시물"],"explanation":["게시물이에요.","188쪽이에요.","올린 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L09_challenge#9','kor',2,2,'u6','L09','g2_2_kor_u6_L09_challenge','lesson_challenge','K2-2-u6-C9',4,'essay','teacher','학급 누리집에 올릴 우리 반 소개 게시물의 주제와 내용을 쓰고, 함께 올릴 그림이나 사진을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u6-C9","difficulty":4,"kind":"essay","stem":"학급 누리집에 올릴 우리 반 소개 게시물의 주제와 내용을 쓰고, 함께 올릴 그림이나 사진을 쓰세요.","answer_guide":{"answer":"예: 주제 — 우리 반이 좋아하는 놀이. 내용 — 우리 반은 쉬는 시간마다 긴 줄넘기를 함께 해요. 사진 — 친구들과 줄넘기를 하는 모습.","scoring_points":["주제와 내용이 맞아요","어울리는 그림·사진이에요"]},"explanation":["주제에 맞게요.","189쪽이에요.","글과 그림을 함께요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_L09_challenge#10','kor',2,2,'u6','L09','g2_2_kor_u6_L09_challenge','lesson_challenge','K2-2-u6-C10',4,'essay','teacher','지도서 274~275쪽 평가 — 인터넷 게시판에 친구의 글이나 사진을 공유하고 싶을 때 주의해야 할 점을 짧은 글로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u6-C10","difficulty":4,"kind":"essay","stem":"지도서 274~275쪽 평가 — 인터넷 게시판에 친구의 글이나 사진을 공유하고 싶을 때 주의해야 할 점을 짧은 글로 쓰세요.","answer_guide":{"answer":"예: 친구의 글이나 사진을 올리기 전에 친구에게 먼저 물어본다. 친구가 싫다고 하면 올리지 않는다. 사진과 함께 고운 말을 쓴다.","scoring_points":["허락을 받는다고 썼어요","고운 말이나 예절을 썼어요"]},"explanation":["주의할 점이에요.","지도서 274쪽이에요.","허락과 예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
