INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_a#16','kor',2,2,'u6','','g2_2_kor_u6_review_a','unit_review','K2-2-u6-C13',2,'mc','auto','『국어』 196쪽 — 「집에 돌아와서 발을 깨끄시 씨섰습니다.」를 바르게 고친 것은?',ARRAY['K2-2-u6-X15']::text[],false,'{"seq":16,"concept":"K2-2-u6-C13","difficulty":2,"kind":"mc","stem":"『국어』 196쪽 — 「집에 돌아와서 발을 깨끄시 씨섰습니다.」를 바르게 고친 것은?","options":[{"t":"집에 돌아와서 발을 깨끗이 씻었습니다.","correct":true},{"t":"집에 돌아와서 발을 깨끄시 씻었습니다.","mis":"K2-2-u6-X15"},{"t":"집에 돌아와서 발을 깨끗시 씨섰습니다.","mis":"K2-2-u6-X15"}],"explanation":["깨끗이 씻었습니다예요.","196쪽 예시 답안이에요.","글자대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
