INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_a#19','kor',2,2,'u6','','g2_2_kor_u6_review_a','unit_review','K2-2-u6-C2',3,'ox','auto','영상은 책보다 언제나 더 좋은 매체이다.',ARRAY['K2-2-u6-X02']::text[],false,'{"seq":19,"concept":"K2-2-u6-C2","difficulty":3,"kind":"ox","stem":"영상은 책보다 언제나 더 좋은 매체이다.","answer":"X","reason_options":[{"t":"책과 영상은 저마다 좋은 점이 달라서","correct":true},{"t":"소리가 나는 매체가 늘 더 좋아서","mis":"K2-2-u6-X02"}],"mis":"K2-2-u6-X02","explanation":["저마다 달라요.","지도서 247쪽이에요.","우열이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_a#20','kor',2,2,'u6','','g2_2_kor_u6_review_a','unit_review','K2-2-u6-C5',3,'mc','auto','철이가 진짜로 오염물이 터지기 전에 막겠다고 마음먹은 까닭은?',ARRAY['K2-2-u6-X07']::text[],false,'{"seq":20,"concept":"K2-2-u6-C5","difficulty":3,"kind":"mc","stem":"철이가 진짜로 오염물이 터지기 전에 막겠다고 마음먹은 까닭은?","options":[{"t":"꿈속에서 물 낭비 때문에 오염물이 터지는 것을 보았기 때문에","correct":true},{"t":"엄마가 막으라고 시켜서","mis":"K2-2-u6-X07"},{"t":"오염물이 귀여워서","mis":"K2-2-u6-X07"}],"explanation":["꿈에서 보았어요.","181쪽이에요.","앞의 일 때문이에요."],"asset":{"type":"passage","lines":["꿈 때문에 마음이 뒤숭숭한 철이는 아침 식사 시간에 음식을 남기지 않고 다 먹었어요.","그런데 집 안 곳곳에서 물이 더러워지고 낭비돼요.","영이는 먹다 남긴 우유를 싱크대에 몰래 부어요.","아빠는 빨래를 세 번이나 나누어 돌려요.","엄마는 샴푸를 많이 쓰고, 물을 튼 채로 욕실 청소를 해요.","집 아래 물길에 까만 오염물이 차오르더니 펑 하고 터져 버려요!","「설마 다 꿈이었나?」 깨어난 철이는 두 볼을 세게 꼬집어 보아요.","철이는 오염물이 터지기 전에 물 오염과 낭비를 막겠다고 마음먹어요."],"title":"『국어』 174~181쪽 「오염물이 터졌다」(송수혜) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_a#21','kor',2,2,'u6','','g2_2_kor_u6_review_a','unit_review','K2-2-u6-C3',3,'mc','auto','이 광고의 글을 보고 알 수 있는 뜻은?',ARRAY['K2-2-u6-X05']::text[],false,'{"seq":21,"concept":"K2-2-u6-C3","difficulty":3,"kind":"mc","stem":"이 광고의 글을 보고 알 수 있는 뜻은?","options":[{"t":"「괜찮겠지」 하고 방심하면 안전사고가 날 수 있어요","correct":true},{"t":"안전사고는 일어나지 않아요","mis":"K2-2-u6-X05"},{"t":"거짓말을 많이 해요","mis":"K2-2-u6-X05"}],"explanation":["방심하지 않아요.","지도서 273쪽이에요.","글과 그림을 함께요."],"asset":{"type":"passage","lines":["큰 글: 「괜찮아, 안전해.」","작은 글: ‘방심’이 하는 거짓말에 속지 마세요. 안전사고는 나를 속이는 작은 거짓말에서 시작합니다.","그림: 녹슨 기둥에 나사가 꽂힌 위험한 곳 앞의 인물"],"title":"지도서 273쪽 평가 예시 광고 2"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_a#22','kor',2,2,'u6','','g2_2_kor_u6_review_a','unit_review','K2-2-u6-C4',3,'mc','auto','『국어』 194쪽 — 정훈이가 할 말로 알맞은 것은?',ARRAY['K2-2-u6-X04']::text[],false,'{"seq":22,"concept":"K2-2-u6-C4","difficulty":3,"kind":"mc","stem":"『국어』 194쪽 — 정훈이가 할 말로 알맞은 것은?","options":[{"t":"글과 그림을 관련지으며 읽으니","correct":true},{"t":"그림만 중심으로 살펴보니","mis":"K2-2-u6-X04"},{"t":"글만 빠르게 읽으니","mis":"K2-2-u6-X04"}],"explanation":["관련지어요.","194쪽 예시 답안이에요.","글과 그림을 함께요."],"asset":{"type":"speech","turns":[{"who":"나래","text":"안녕, 정훈아? 반가워."},{"who":"나래","text":"주말에 글과 그림이 있는 만화를 읽으려고 해. 만화나 그림책을 읽을 때에는 어떤 점을 생각하며 읽으면 좋을까?"},{"who":"정훈","text":"나는 만화나 그림책을 읽을 때 (    ) 그 내용을 더 잘 이해할 수 있어서 좋았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_a#23','kor',2,2,'u6','','g2_2_kor_u6_review_a','unit_review','K2-2-u6-C1',4,'sa','auto','책, 텔레비전, 스마트폰처럼 서로 소통하게 이어 주는 도구를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u6-C1","difficulty":4,"kind":"sa","stem":"책, 텔레비전, 스마트폰처럼 서로 소통하게 이어 주는 도구를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["매체"],"explanation":["매체예요.","지도서 257쪽이에요.","소통을 이어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_a#24','kor',2,2,'u6','','g2_2_kor_u6_review_a','unit_review','K2-2-u6-C3',4,'essay','teacher','지도서 272~273쪽 평가 — 이 광고를 보고 흥미와 관심을 가지게 된 글이나 그림 하나와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u6-C3","difficulty":4,"kind":"essay","stem":"지도서 272~273쪽 평가 — 이 광고를 보고 흥미와 관심을 가지게 된 글이나 그림 하나와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「괜찮아, 안전해.」라는 글이 인상 깊었다. 괜찮다고 생각하는 마음이 오히려 사고를 부를 수 있다는 것을 알게 되었기 때문이다.","scoring_points":["글이나 그림을 골랐어요","까닭을 썼어요"]},"explanation":["까닭과 함께요.","지도서 272쪽이에요.","흥미와 관심이에요."],"asset":{"type":"passage","lines":["큰 글: 「괜찮아, 안전해.」","작은 글: ‘방심’이 하는 거짓말에 속지 마세요. 안전사고는 나를 속이는 작은 거짓말에서 시작합니다.","그림: 녹슨 기둥에 나사가 꽂힌 위험한 곳 앞의 인물"],"title":"지도서 273쪽 평가 예시 광고 2"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_a#25','kor',2,2,'u6','','g2_2_kor_u6_review_a','unit_review','K2-2-u6-C8',4,'essay','teacher','지도서 274~275쪽 평가 — 인터넷 게시판에 친구의 글이나 사진을 공유하고 싶을 때 주의해야 할 점을 짧은 글로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u6-C8","difficulty":4,"kind":"essay","stem":"지도서 274~275쪽 평가 — 인터넷 게시판에 친구의 글이나 사진을 공유하고 싶을 때 주의해야 할 점을 짧은 글로 쓰세요.","answer_guide":{"answer":"예: 친구의 글이나 사진을 올리기 전에 먼저 친구에게 물어본다. 친구가 싫다고 하면 올리지 않는다. 한번 올린 것은 쉽게 지워지지 않기 때문이다.","scoring_points":["허락을 받는다고 썼어요","까닭이나 예절을 썼어요"]},"explanation":["주의할 점이에요.","지도서 274쪽이에요.","허락이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
