INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_b#3','kor',2,2,'u6','','g2_2_kor_u6_review_b','unit_review','K2-2-u6-C2',1,'mc','auto','「토끼의 재판」을 영상으로 볼 때 좋은 점은?',ARRAY['K2-2-u6-X03']::text[],false,'{"seq":3,"concept":"K2-2-u6-C2","difficulty":1,"kind":"mc","stem":"「토끼의 재판」을 영상으로 볼 때 좋은 점은?","options":[{"t":"소리를 들으며 움직임을 생생하게 볼 수 있어요","correct":true},{"t":"종이를 넘기며 읽을 수 있어요","mis":"K2-2-u6-X03"},{"t":"글자를 짚으며 읽을 수 있어요","mis":"K2-2-u6-X03"}],"explanation":["움직임과 소리예요.","168쪽이에요.","영상의 좋은 점이에요."],"asset":{"type":"speech","turns":[{"who":"소현","text":"「토끼의 재판」을 책으로 읽으니 재판하는 모습을 상상할 수 있어서 좋아."},{"who":"다훈","text":"종이를 넘기면서 한 글자, 한 글자 읽다 보니까 이야기 속으로 빠져들었어."},{"who":"다훈","text":"「토끼의 재판」을 영상으로 보니 소리를 들으며 인물들의 움직임을 볼 수 있어서 그 모습이 더 생생하게 느껴져."},{"who":"소현","text":"영상 속 호랑이 소리가 진짜 호랑이가 우는 소리처럼 실감 나게 느껴졌어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_b#4','kor',2,2,'u6','','g2_2_kor_u6_review_b','unit_review','K2-2-u6-C3',1,'mc','auto','『국어』 170쪽 공익 광고에서 풀처럼 보이는 것은 사실 무엇인가요?',ARRAY['K2-2-u6-X05','K2-2-u6-X04']::text[],false,'{"seq":4,"concept":"K2-2-u6-C3","difficulty":1,"kind":"mc","stem":"『국어』 170쪽 공익 광고에서 풀처럼 보이는 것은 사실 무엇인가요?","options":[{"t":"비닐봉지","correct":true},{"t":"나뭇잎","mis":"K2-2-u6-X05"},{"t":"종이","mis":"K2-2-u6-X04"}],"explanation":["비닐봉지예요.","171쪽이에요.","썩지 않아요."],"asset":{"type":"passage","lines":["그림: 흙 위에 초록색 비닐봉지가 풀처럼 솟아 있어요.","큰 글: 「엄마, 저 풀은 이름이 뭐예요?」","작은 글: 땅속에 묻어도 썩지 않는 쓰레기들이 토양을 오염시키고 있습니다."],"title":"『국어』 170쪽 공익 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_b#5','kor',2,2,'u6','','g2_2_kor_u6_review_b','unit_review','K2-2-u6-C4',1,'mc','auto','장면 2에서 「영준아, 천천히 가자.」라고 말한 사람은?',ARRAY['K2-2-u6-X06','K2-2-u6-X07']::text[],false,'{"seq":5,"concept":"K2-2-u6-C4","difficulty":1,"kind":"mc","stem":"장면 2에서 「영준아, 천천히 가자.」라고 말한 사람은?","options":[{"t":"아버지","correct":true},{"t":"영준","mis":"K2-2-u6-X06"},{"t":"어머니","mis":"K2-2-u6-X07"}],"explanation":["아버지예요.","172쪽이에요.","말풍선을 봐요."],"asset":{"type":"passage","lines":["장면 1 — 영준: 야호! 신난다. (산길을 뛰어 내려가요)","장면 2 — 아버지: 영준아, 천천히 가자. / 영준: 우아, 내려가는 건 정말 쉬워요.","장면 3 — 꽈당! 영준: 아야, 아파라!","장면 4 — 어머니와 아버지가 넘어진 영준이에게 다가와 살펴요."],"title":"『국어』 172쪽 만화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_b#6','kor',2,2,'u6','','g2_2_kor_u6_review_b','unit_review','K2-2-u6-C5',1,'mc','auto','빨래를 세 번 나누어 돌린 사람은?',ARRAY['K2-2-u6-X07']::text[],false,'{"seq":6,"concept":"K2-2-u6-C5","difficulty":1,"kind":"mc","stem":"빨래를 세 번 나누어 돌린 사람은?","options":[{"t":"아빠","correct":true},{"t":"엄마","mis":"K2-2-u6-X07"},{"t":"영이","mis":"K2-2-u6-X07"}],"explanation":["아빠예요.","174쪽이에요.","장면을 봐요."],"asset":{"type":"passage","lines":["꿈 때문에 마음이 뒤숭숭한 철이는 아침 식사 시간에 음식을 남기지 않고 다 먹었어요.","그런데 집 안 곳곳에서 물이 더러워지고 낭비돼요.","영이는 먹다 남긴 우유를 싱크대에 몰래 부어요.","아빠는 빨래를 세 번이나 나누어 돌려요.","엄마는 샴푸를 많이 쓰고, 물을 튼 채로 욕실 청소를 해요.","집 아래 물길에 까만 오염물이 차오르더니 펑 하고 터져 버려요!","「설마 다 꿈이었나?」 깨어난 철이는 두 볼을 세게 꼬집어 보아요.","철이는 오염물이 터지기 전에 물 오염과 낭비를 막겠다고 마음먹어요."],"title":"『국어』 174~181쪽 「오염물이 터졌다」(송수혜) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_b#7','kor',2,2,'u6','','g2_2_kor_u6_review_b','unit_review','K2-2-u6-C7',1,'mc','auto','어린이박물관 누리집에서 관람 예약을 할 때 누를 단추는?',ARRAY['K2-2-u6-X09']::text[],false,'{"seq":7,"concept":"K2-2-u6-C7","difficulty":1,"kind":"mc","stem":"어린이박물관 누리집에서 관람 예약을 할 때 누를 단추는?","options":[{"t":"관람 예약","correct":true},{"t":"교육 예약","mis":"K2-2-u6-X09"},{"t":"소개","mis":"K2-2-u6-X09"}],"explanation":["관람 예약이에요.","184쪽이에요.","단추 이름을 봐요."],"asset":{"type":"passage","lines":["차림표: 관람 · 전시 · 교육 · 자료 · 소개","큰 글: 「새로운 공간을 소개합니다!」와 박물관 안내도","관람 시간과 관람료","날짜별 관람 예약 현황","단추: 「관람 예약」 · 「교육 예약」"],"title":"『국어』 184쪽 국립중앙박물관 어린이박물관 누리집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
