INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_b#22','kor',2,2,'u6','','g2_2_kor_u6_review_b','unit_review','K2-2-u6-C7',3,'mc','auto','『국어』 195쪽 — 매체에 흥미를 가질 때 주의할 점을 바르게 말한 친구는?',ARRAY['K2-2-u6-X02','K2-2-u6-X09']::text[],false,'{"seq":22,"concept":"K2-2-u6-C7","difficulty":3,"kind":"mc","stem":"『국어』 195쪽 — 매체에 흥미를 가질 때 주의할 점을 바르게 말한 친구는?","options":[{"t":"홍철: 매체와 매체 자료가 알맞은 내용을 담고 있는지 생각해 봐야 해.","correct":true},{"t":"찬석: 내가 좋아하는 매체는 나만 아는 것이 좋아.","mis":"K2-2-u6-X02"},{"t":"소현: 모든 매체에 흥미와 관심을 가지는 것이 좋아.","mis":"K2-2-u6-X09"}],"explanation":["알맞은 내용인지요.","195쪽 예시 답안이에요.","경아도 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_b#23','kor',2,2,'u6','','g2_2_kor_u6_review_b','unit_review','K2-2-u6-C9',4,'sa','auto','누리집에 올린 글·그림·사진 같은 자료를 세 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u6-C9","difficulty":4,"kind":"sa","stem":"누리집에 올린 글·그림·사진 같은 자료를 세 글자로 쓰세요.","answer":["게시물"],"explanation":["게시물이에요.","188쪽이에요.","올린 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_b#24','kor',2,2,'u6','','g2_2_kor_u6_review_b','unit_review','K2-2-u6-C3',4,'essay','teacher','이 광고에서 흥미와 관심을 가지게 된 글이나 그림 하나와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u6-C3","difficulty":4,"kind":"essay","stem":"이 광고에서 흥미와 관심을 가지게 된 글이나 그림 하나와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 지구 위에 여러 동물이 함께 있는 그림이 좋았다. 동물들이 살 수 있는 지구를 우리가 지켜야 한다는 생각이 들었다.","scoring_points":["글이나 그림을 골랐어요","까닭을 썼어요"]},"explanation":["까닭과 함께요.","지도서 273쪽이에요.","흥미와 관심이에요."],"asset":{"type":"passage","lines":["큰 글: 「꿈과 미래가 있는 지구」 우리가 보호해야 합니다.","그림: 여러 동물과 열기구가 함께 있는 둥근 지구"],"title":"지도서 273쪽 평가 예시 광고 3"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_b#25','kor',2,2,'u6','','g2_2_kor_u6_review_b','unit_review','K2-2-u6-C9',4,'essay','teacher','우리 반을 소개하는 게시물 글을 두 문장으로 쓰고, 함께 올릴 그림이나 사진을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u6-C9","difficulty":4,"kind":"essay","stem":"우리 반을 소개하는 게시물 글을 두 문장으로 쓰고, 함께 올릴 그림이나 사진을 쓰세요.","answer_guide":{"answer":"예: 우리 반은 쉬는 시간마다 긴 줄넘기를 해요. 모두 함께 넘으면 웃음이 터져요. 사진 — 친구들과 줄넘기를 하는 모습.","scoring_points":["우리 반을 소개했어요","어울리는 그림·사진이에요"]},"explanation":["글과 그림이에요.","190쪽이에요.","어울리게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
