INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_c#3','kor',2,2,'u6','','g2_2_kor_u6_review_c','unit_review','K2-2-u6-C2',1,'mc','auto','소현이가 호랑이 소리가 실감 났다고 한 것은 어떤 매체로 볼 때인가요?',ARRAY['K2-2-u6-X03']::text[],false,'{"seq":3,"concept":"K2-2-u6-C2","difficulty":1,"kind":"mc","stem":"소현이가 호랑이 소리가 실감 났다고 한 것은 어떤 매체로 볼 때인가요?","options":[{"t":"영상","correct":true},{"t":"책","mis":"K2-2-u6-X03"},{"t":"신문","mis":"K2-2-u6-X03"}],"explanation":["영상이에요.","168쪽이에요.","소리가 나요."],"asset":{"type":"speech","turns":[{"who":"소현","text":"「토끼의 재판」을 책으로 읽으니 재판하는 모습을 상상할 수 있어서 좋아."},{"who":"다훈","text":"종이를 넘기면서 한 글자, 한 글자 읽다 보니까 이야기 속으로 빠져들었어."},{"who":"다훈","text":"「토끼의 재판」을 영상으로 보니 소리를 들으며 인물들의 움직임을 볼 수 있어서 그 모습이 더 생생하게 느껴져."},{"who":"소현","text":"영상 속 호랑이 소리가 진짜 호랑이가 우는 소리처럼 실감 나게 느껴졌어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_c#4','kor',2,2,'u6','','g2_2_kor_u6_review_c','unit_review','K2-2-u6-C3',1,'mc','auto','『국어』 170쪽 공익 광고의 큰 글은?',ARRAY['K2-2-u6-X04']::text[],false,'{"seq":4,"concept":"K2-2-u6-C3","difficulty":1,"kind":"mc","stem":"『국어』 170쪽 공익 광고의 큰 글은?","options":[{"t":"「엄마, 저 풀은 이름이 뭐예요?」","correct":true},{"t":"「불이야!」","mis":"K2-2-u6-X04"},{"t":"「반려동물은 가족입니다」","mis":"K2-2-u6-X04"}],"explanation":["풀 이름을 묻는 글이에요.","170쪽이에요.","글을 살펴요."],"asset":{"type":"passage","lines":["그림: 흙 위에 초록색 비닐봉지가 풀처럼 솟아 있어요.","큰 글: 「엄마, 저 풀은 이름이 뭐예요?」","작은 글: 땅속에 묻어도 썩지 않는 쓰레기들이 토양을 오염시키고 있습니다."],"title":"『국어』 170쪽 공익 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_c#5','kor',2,2,'u6','','g2_2_kor_u6_review_c','unit_review','K2-2-u6-C4',1,'mc','auto','장면 3에서 영준이의 표정은?',ARRAY['K2-2-u6-X06']::text[],false,'{"seq":5,"concept":"K2-2-u6-C4","difficulty":1,"kind":"mc","stem":"장면 3에서 영준이의 표정은?","options":[{"t":"아파하는 표정","correct":true},{"t":"활짝 웃는 표정","mis":"K2-2-u6-X06"},{"t":"졸린 표정","mis":"K2-2-u6-X06"}],"explanation":["아파해요.","172쪽 예시 답안이에요.","넘어졌어요."],"asset":{"type":"passage","lines":["장면 1 — 영준: 야호! 신난다. (산길을 뛰어 내려가요)","장면 2 — 아버지: 영준아, 천천히 가자. / 영준: 우아, 내려가는 건 정말 쉬워요.","장면 3 — 꽈당! 영준: 아야, 아파라!","장면 4 — 어머니와 아버지가 넘어진 영준이에게 다가와 살펴요."],"title":"『국어』 172쪽 만화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_c#6','kor',2,2,'u6','','g2_2_kor_u6_review_c','unit_review','K2-2-u6-C5',1,'mc','auto','샴푸를 많이 쓴 사람은?',ARRAY['K2-2-u6-X07']::text[],false,'{"seq":6,"concept":"K2-2-u6-C5","difficulty":1,"kind":"mc","stem":"샴푸를 많이 쓴 사람은?","options":[{"t":"엄마","correct":true},{"t":"영이","mis":"K2-2-u6-X07"},{"t":"철이","mis":"K2-2-u6-X07"}],"explanation":["엄마예요.","174쪽이에요.","장면을 봐요."],"asset":{"type":"passage","lines":["꿈 때문에 마음이 뒤숭숭한 철이는 아침 식사 시간에 음식을 남기지 않고 다 먹었어요.","그런데 집 안 곳곳에서 물이 더러워지고 낭비돼요.","영이는 먹다 남긴 우유를 싱크대에 몰래 부어요.","아빠는 빨래를 세 번이나 나누어 돌려요.","엄마는 샴푸를 많이 쓰고, 물을 튼 채로 욕실 청소를 해요.","집 아래 물길에 까만 오염물이 차오르더니 펑 하고 터져 버려요!","「설마 다 꿈이었나?」 깨어난 철이는 두 볼을 세게 꼬집어 보아요.","철이는 오염물이 터지기 전에 물 오염과 낭비를 막겠다고 마음먹어요."],"title":"『국어』 174~181쪽 「오염물이 터졌다」(송수혜) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
