INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_c#24','kor',2,2,'u6','','g2_2_kor_u6_review_c','unit_review','K2-2-u6-C4',4,'essay','teacher','만화나 그림책을 볼 때 글과 그림을 관련지어 읽으면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u6-C4","difficulty":4,"kind":"essay","stem":"만화나 그림책을 볼 때 글과 그림을 관련지어 읽으면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 글과 그림을 관련지어 읽으면 인물의 표정으로 마음을 알 수 있어서 내용을 더 잘 이해할 수 있다.","scoring_points":["글과 그림을 함께 말했어요","좋은 점을 썼어요"]},"explanation":["관련지어요.","지도서 257쪽이에요.","더 잘 이해해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
