INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_d#6','kor',2,2,'u6','','g2_2_kor_u6_review_d','unit_review','K2-2-u6-C5',1,'mc','auto','꿈 때문에 마음이 뒤숭숭한 사람은?',ARRAY['K2-2-u6-X07']::text[],false,'{"seq":6,"concept":"K2-2-u6-C5","difficulty":1,"kind":"mc","stem":"꿈 때문에 마음이 뒤숭숭한 사람은?","options":[{"t":"철이","correct":true},{"t":"엄마","mis":"K2-2-u6-X07"},{"t":"아빠","mis":"K2-2-u6-X07"}],"explanation":["철이예요.","174쪽이에요.","첫 장면이에요."],"asset":{"type":"passage","lines":["꿈 때문에 마음이 뒤숭숭한 철이는 아침 식사 시간에 음식을 남기지 않고 다 먹었어요.","그런데 집 안 곳곳에서 물이 더러워지고 낭비돼요.","영이는 먹다 남긴 우유를 싱크대에 몰래 부어요.","아빠는 빨래를 세 번이나 나누어 돌려요.","엄마는 샴푸를 많이 쓰고, 물을 튼 채로 욕실 청소를 해요.","집 아래 물길에 까만 오염물이 차오르더니 펑 하고 터져 버려요!","「설마 다 꿈이었나?」 깨어난 철이는 두 볼을 세게 꼬집어 보아요.","철이는 오염물이 터지기 전에 물 오염과 낭비를 막겠다고 마음먹어요."],"title":"『국어』 174~181쪽 「오염물이 터졌다」(송수혜) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
