INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_d#19','kor',2,2,'u6','','g2_2_kor_u6_review_d','unit_review','K2-2-u6-C4',3,'ox','auto','만화를 읽을 때는 말풍선과 인물의 표정을 함께 보는 것이 좋다.',ARRAY['K2-2-u6-X04']::text[],false,'{"seq":19,"concept":"K2-2-u6-C4","difficulty":3,"kind":"ox","stem":"만화를 읽을 때는 말풍선과 인물의 표정을 함께 보는 것이 좋다.","answer":"O","reason_options":[{"t":"글과 그림을 관련지으면 내용을 더 생생하게 알 수 있어서","correct":true},{"t":"그림만 보면 충분해서","mis":"K2-2-u6-X04"}],"mis":"K2-2-u6-X04","explanation":["함께 봐요.","173쪽이에요.","생생하게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_d#20','kor',2,2,'u6','','g2_2_kor_u6_review_d','unit_review','K2-2-u6-C5',3,'mc','auto','「오염물이 터졌다」가 우리에게 전하려는 뜻은?',ARRAY['K2-2-u6-X07']::text[],false,'{"seq":20,"concept":"K2-2-u6-C5","difficulty":3,"kind":"mc","stem":"「오염물이 터졌다」가 우리에게 전하려는 뜻은?","options":[{"t":"물을 아끼고 더럽히지 말아야 해요","correct":true},{"t":"우유를 많이 마셔요","mis":"K2-2-u6-X07"},{"t":"빨래를 하지 말아요","mis":"K2-2-u6-X07"}],"explanation":["물을 아껴요.","지도서 253쪽이에요.","수질 오염이에요."],"asset":{"type":"passage","lines":["꿈 때문에 마음이 뒤숭숭한 철이는 아침 식사 시간에 음식을 남기지 않고 다 먹었어요.","그런데 집 안 곳곳에서 물이 더러워지고 낭비돼요.","영이는 먹다 남긴 우유를 싱크대에 몰래 부어요.","아빠는 빨래를 세 번이나 나누어 돌려요.","엄마는 샴푸를 많이 쓰고, 물을 튼 채로 욕실 청소를 해요.","집 아래 물길에 까만 오염물이 차오르더니 펑 하고 터져 버려요!","「설마 다 꿈이었나?」 깨어난 철이는 두 볼을 세게 꼬집어 보아요.","철이는 오염물이 터지기 전에 물 오염과 낭비를 막겠다고 마음먹어요."],"title":"『국어』 174~181쪽 「오염물이 터졌다」(송수혜) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_d#21','kor',2,2,'u6','','g2_2_kor_u6_review_d','unit_review','K2-2-u6-C2',3,'mc','auto','영상 「토끼의 재판」을 실감 나게 보는 방법으로 알맞은 것은?',ARRAY['K2-2-u6-X03']::text[],false,'{"seq":21,"concept":"K2-2-u6-C2","difficulty":3,"kind":"mc","stem":"영상 「토끼의 재판」을 실감 나게 보는 방법으로 알맞은 것은?","options":[{"t":"인물의 움직임과 소리에 집중해요","correct":true},{"t":"소리를 끄고 봐요","mis":"K2-2-u6-X03"},{"t":"끝부분만 봐요","mis":"K2-2-u6-X03"}],"explanation":["움직임과 소리예요.","169쪽이에요.","영상의 좋은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_d#22','kor',2,2,'u6','','g2_2_kor_u6_review_d','unit_review','K2-2-u6-C10',3,'mc','auto','게시물을 점검할 때 확인할 것으로 알맞지 않은 것은?',ARRAY['K2-2-u6-X11']::text[],false,'{"seq":22,"concept":"K2-2-u6-C10","difficulty":3,"kind":"mc","stem":"게시물을 점검할 때 확인할 것으로 알맞지 않은 것은?","options":[{"t":"글씨 색이 몇 가지인가요?","correct":true},{"t":"다른 사람들이 궁금해할 만한 내용인가요?","mis":"K2-2-u6-X11"},{"t":"그림이나 사진이 글의 내용과 잘 어울리나요?","mis":"K2-2-u6-X11"}],"explanation":["색은 아니에요.","190쪽이에요.","세 가지를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_d#23','kor',2,2,'u6','','g2_2_kor_u6_review_d','unit_review','K2-2-u6-C3',4,'sa','auto','「○○ 광고」는 여러 사람의 이익을 목적으로 하는 광고예요. 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u6-C3","difficulty":4,"kind":"sa","stem":"「○○ 광고」는 여러 사람의 이익을 목적으로 하는 광고예요. 빈칸 두 글자를 쓰세요.","answer":["공익"],"explanation":["공익이에요.","170쪽이에요.","공익 광고예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_d#24','kor',2,2,'u6','','g2_2_kor_u6_review_d','unit_review','K2-2-u6-C2',4,'essay','teacher','자신이 좋아하는 매체를 하나 골라 그 좋은 점을 소개하는 글을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u6-C2","difficulty":4,"kind":"essay","stem":"자신이 좋아하는 매체를 하나 골라 그 좋은 점을 소개하는 글을 쓰세요.","answer_guide":{"answer":"예: 나는 그림책을 좋아한다. 그림을 보며 이야기를 상상할 수 있고, 가족과 함께 읽을 수 있어서 좋다.","scoring_points":["매체를 골랐어요","좋은 점을 까닭과 함께 썼어요"]},"explanation":["좋은 점을 소개해요.","지도서 269쪽 예시 2예요.","까닭과 함께요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u6_review_d#25','kor',2,2,'u6','','g2_2_kor_u6_review_d','unit_review','K2-2-u6-C5',4,'essay','teacher','「오염물이 터졌다」를 읽고 철이처럼 물을 아끼려고 실천할 일을 두 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u6-C5","difficulty":4,"kind":"essay","stem":"「오염물이 터졌다」를 읽고 철이처럼 물을 아끼려고 실천할 일을 두 가지 쓰세요.","answer_guide":{"answer":"예: 이를 닦을 때 컵에 물을 받아 쓴다. 먹다 남은 음식이나 우유를 싱크대에 버리지 않는다.","scoring_points":["실천할 일이 두 가지예요","물을 아끼는 일이에요"]},"explanation":["실천이에요.","183쪽이에요.","생활과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
